SELECT DISTINCTROW [Gesamt Normierung].Elektrolyseur, [Gesamt Normierung].Datum, [Gesamt Normierung].Zeit, [Gesamt Normierung].[I Gesamt], ([Gesamt Normierung]![I Gesamt]/GetGewFlaeche()) AS i, [Gesamt Normierung].Cc, [Gesamt Normierung].[t An], [Gesamt Normierung].[t Ka], ([Gesamt Normierung]![t An]+[Gesamt Normierung]![t Ka])/2 AS tm, [Gesamt Normierung].Uo, [Gesamt Normierung].Position, [Gesamt Normierung].Ui, Um.[Mittelwert von Ui], [Gesamt Normierung].Un AS UnAlt, [tm]-([Mittelwert von Ui]-[Ui])*30 AS tiAlt, TempKorrElement([tm],[Mittelwert von Ui],[Ui]) AS ti, UnBer([Ui],[i],[ti],[Gesamt Normierung]![Cc]) AS Un
FROM [Gesamt Normierung] INNER JOIN Um ON ([Gesamt Normierung].Datum = Um.Datum) AND ([Gesamt Normierung].Elektrolyseur = Um.Elektrolyseur)
ORDER BY [Gesamt Normierung].Elektrolyseur, [Gesamt Normierung].Datum, [Gesamt Normierung].Zeit, [Gesamt Normierung].Position;
